onClick:
{{
  !selEditEmployee.selectedOptionValue
    ? showAlert("Please select an employee first.", "warning")
    : q_hr_deactivate_employee.run()
        .then(data => {
          if (!data || data.length === 0) {
            showAlert(
              "Employee was not deactivated. They may already be inactive or have pending leave requests.",
              "warning"
            );
            return;
          }

          showAlert("Employee deactivated successfully.", "success");

          return Promise.all([
            q_hr_get_employees.run(),
            q_hr_get_employees_for_edit.run(),
            q_hr_get_employee_by_id.run(),
            q_hr_get_leave_balances.run()
          ]);
        })
        .catch(error => {
          showAlert(error.message || "Unable to deactivate employee.", "error");
        })
}}
